	/**
	 * The matrix as the admin shell reads it.
	 *
	 * @return array<int, array{id: string, area: string, title: string, min: string, compare: bool}>
	 */
	public static function for_js(): array {
		$titles = self::titles();
		$areas  = self::areas();
		$out    = array();
		foreach ( self::ROWS as $id => $row ) {
			$out[] = array(
				'id'      => $id,
				'area'    => $areas[ $row[0] ] ?? '',
				'title'   => $titles[ $id ] ?? $id,
				'min'     => self::MIN_PLAN[ $id ],
				'compare' => $row[1],
			);
		}

		return $out;
	}
